/** Never send an NPC hand, concealed target item, or submitted opposing hand to a client. */
export function theftViewFor(state: AppraisalState, p: Appraiser): TheftView {
  const crime = (p as Thief).crime;
  return {
    duels: ((state as TheftState).theftDuels ?? []).filter(d => d.encounter === state.encounter && [d.thiefId,d.victimId].includes(p.id)).map(d => ({
      id:d.id, thiefId:d.thiefId, ...(d.victimId ? {victimId:d.victimId} : d.npc ? {npc:d.npc} : {}),
      ...(d.npc ? {npcTell:npcTheftTell(d.npc)} : {}),
      round:d.round, status:d.status, needsChoice:d.status === 'open' && !d.hands[p.id], submitted:!!d.hands[p.id],
      ...(state.config.statusLinks === 1 && d.status === 'open' ? tieView(state,d,p) : {}),
      revealed:d.revealed.map(r => ({...r})),
    })),
    targets: state.players.filter(v => v.id !== p.id && !v.paused && !v.done).map(v => {
      const until = pvpBlockedUntil(state,p,v.id);
      return {playerId:v.id,...(until !== undefined ? {blockedUntilEncounter:until} : {})};
    }),
    compensation: ((state as TheftState).compensations ?? []).filter(c => [c.thiefId,c.victimId].includes(p.id)).map(c => ({
      id:c.id,role:c.thiefId === p.id ? 'payer' as const : 'receiver' as const,otherId:c.thiefId === p.id ? c.victimId : c.thiefId,
      amount:c.amount,remaining:c.dueEncounters.filter(e => !c.settled.some(s => s.encounter === e)),paid:c.settled.reduce((sum,s) => sum+s.paid,0),
    })),
    seals: ((state as TheftState).sinnerSeals ?? []).filter(seal => seal.holderId === p.id).map(seal => ({id:seal.id,thiefId:seal.thiefId})),
    ...(crime ? {crime:{failures:crime.failures,banStartsEncounter:crime.banStartsEncounter,banUntilEncounter:crime.banUntilEncounter,active:merchantTradeBanned(state,p),noticePrice:noticePrice(crime),cases:crime.cases.length}} : {}),
  };
}

import type { Appraiser, Knowledge, MarketContract, MarketOrder, NpcId } from './types.js';

export const TRUST_CAP=10;
export function trustAcceptanceBonus(p:Pick<Appraiser,'npcTrust'>,npc:NpcId):number {return (p.npcTrust?.[npc]??0)*.05;}
export function marketOrderReserve(order:MarketOrder):number {return order.price*(order.rarityReserveMultiplier??1)+(order.contract?.bonus.kind==='credits'?order.contract.bonus.amount:0);}
/** Accept only visible facts on the client; an unknown property must never become a quote oracle. */
export function marketConditionMatch(contract:MarketContract,facts:Pick<Knowledge,'genuine'|'cursed'>):'match'|'mismatch'|'unknown' {
  if(contract.requirements.some(r=>facts[r.property]!==undefined && facts[r.property]!==r.value))return 'mismatch';
  return contract.requirements.every(r=>facts[r.property]!==undefined)?'match':'unknown';
}
export function makeMarketContract(roll:(key:string)=>number,survival:boolean):MarketContract {
  const requirements:MarketContract['requirements'][]=[
    [{property:'genuine',value:true}],[{property:'cursed',value:false}],
    [{property:'genuine',value:true},{property:'cursed',value:false}],
    [{property:'genuine',value:false}],[{property:'cursed',value:true}],
    [{property:'genuine',value:true},{property:'cursed',value:true}],
  ];
  const bonusIndex=Math.floor(roll('bonus')*4),costIndex=Math.floor(roll('cost')*3);
  const bonus:MarketContract['bonus']=bonusIndex===0?{kind:'credits',amount:3}:bonusIndex===1?{kind:'energy',amount:2}:bonusIndex===2 && survival?{kind:'life',amount:1}:{kind:'buff',statusId:'B03'};
  const fullPriceCost:MarketContract['fullPriceCost']=costIndex===0?{kind:'energy',amount:2}:costIndex===1 && survival?{kind:'life',amount:1}:{kind:'debuff',statusId:'D01'};
  return {requirements:requirements[Math.floor(roll('requirements')*requirements.length)]!,bonus,fullPriceCost};
}

test('NPC hand is sealed before choice; draws replay without spending another attempt or energy',()=>{
  const state = fixture(); const p = state.players[0]!;
  startTheftDuel(state,p,{itemId:p.stock[0]!});
  const duel = latest(state); const sealed = duel.hands.npc!;
  const before = JSON.stringify(theftViewFor(state,p));
  assert.equal(before.includes('"hands"'),false);
  assert.equal(before.includes('"itemId"'),false);
  assert.deepEqual(theftViewFor(state,p).duels[0]!.revealed,[]);
  chooseTheftHand(state,p,duel.id,sealed);
  assert.equal(duel.status,'open'); assert.equal(duel.round,2);
  assert.deepEqual(duel.revealed,[{thief:sealed,opponent:sealed}]);
  assert.equal(p.energy,7); assert.equal(p.stealTried!.length,1);
  chooseTheftHand(state,p,duel.id,beats[duel.hands.npc!]);
  assert.equal(duel.status,'won'); assert.equal(p.energy,7);
  assert.equal(state.items[duel.itemId]!.owner,p.id);
  assert.equal(p.inventory.filter(id=>id===duel.itemId).length,1);
  assert.equal(p.theft,undefined);
  assert.throws(()=>startTheftDuel(state,p,{itemId:p.stock[0]!}));
});

test('same seed and choices replay identical NPC hands and results',()=>{
  const first = fixture(); const second = fixture();
  for(const state of [first,second]) {
    const p = state.players[0]!;
    startTheftDuel(state,p,{itemId:p.stock[0]!});
    const d = latest(state);
    chooseTheftHand(state,p,d.id,d.hands.npc!);
    chooseTheftHand(state,p,d.id,'paper');
  }
  assert.deepEqual(first,second);
});
